mapper.select:
SELECT 
FROM equipment_repair_hist r
JOIN base_equipment e ON e.equip_id = r.equip_id

    AND r.fail_dt >= #{from}
    AND r.fail_dt < #{to}
    AND r.equip_id = #{equipId}
    AND r.status = #{status}
    AND r.repair_kind = #{repairKind}

        AND (r.repair_no LIKE CONCAT('%', #{keyword}, '%')
             OR r.fail_type LIKE CONCAT('%', #{keyword}, '%')
             OR r.symptom LIKE CONCAT('%', #{keyword}, '%')
             OR r.alarm_code LIKE CONCAT('%', #{keyword}, '%')
             OR r.repairer_name LIKE CONCAT('%', #{keyword}, '%')
             OR r.vendor_name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY r.fail_dt DESC, r.repair_id DESC

mapper.insert:
