    part_cost, outsource_cost, reg_user_id, reg_user_name
) VALUES (
    #{repairNo}, #{equipId}, #{failDt}, #{failType}, #{alarmCode}, #{symptom}, #{cause}, #{action},
    #{repairerName}, #{repairKind}, #{vendorName}, #{startDt}, #{endDt}, #{recoverDt}, #{testResult}, #{status},
    #{partCost}, #{outsourceCost}, #{regUserId}, #{regUserName}
)
